/* Base styles with zero specificity: any class can override them */
:where(h1, h2, h3) {
  line-height: 1.2;
  margin-block: 0 0.5em;
}

/* A component rule: one class, easy to override later */
.card-title {
  margin-block: 0;
}

/* Only ever beaten by another !important rule with higher specificity */
.sr-only {
  position: absolute !important;
}

body {
  color: #1e3a8a;
  font-family: Georgia, serif;   /* inherited by headings, paragraphs, list items... */
}

button {
  font: inherit;                 /* ...and now by the button too */
  color: inherit;
  padding: 0.5rem 1rem;
}

.card {
  border: 2px solid;             /* not inherited: the card's h2 and p get no border */
  padding: 1rem;
}

@layer reset, base, components;   /* declare the order first */

@layer reset {
  *, *::before, *::after { box-sizing: border-box; margin: 0; }
}

@layer base {
  #main a { color: #1d4ed8; }       /* 1-0-1, but in an earlier layer... */
}

@layer components {
  .nav-link { color: white; }       /* ...so this 0-1-0 rule still wins */
}
